static inline int get_se_golomb_long(GetBitContext *gb) /* <=== get_se_golomb_long */ 
{
    unsigned int buf = get_ue_golomb_long(gb);
    int sign = (buf & 1) - 1;
    return ((buf >> 1) ^ sign) + 1;
}

static inline unsigned int show_bits_long(GetBitContext *s, int n) /* <=== show_bits_long */ 
{
    if (n <= MIN_CACHE_BITS) {
        return show_bits(s, n);
    } else {
        GetBitContext gb = *s;
        return get_bits_long(&gb, n);
    }
}

